42	namespace prim = ::sg::sm90::primitives;
43	using ::sg::algorithms::grokfast_fused_step;
44	
45	// Minimum resident blocks/SM for the bandwidth-bound element-wise applies.
46	// Caps registers so occupancy stays high on the memory-bound path.
47	#ifndef SG_GROKFAST_MIN_BLOCKS
48	#define SG_GROKFAST_MIN_BLOCKS 4
49	#endif
50	
51	// SG_TUNED_UNROLL-parameterized scalar grid-stride kernel. Each iteration
52	// processes UNROLL elements; the canonical per-element grokfast_fused_step is
53	// CALLED (math single-sourced in algorithms/grokfast.h) — the unroll only
54	// changes the loop structure the autotuner generates, not the math.
55	template <typename ParamT, typename GradT, int UNROLL>
56	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKFAST_MIN_BLOCKS)
57	grokfast_kernel(
58	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* ema,
59	    const GradT* grad,
60	    float gf_alpha, float gf_lamb,
61	    float lr, float beta1, float beta2, float eps, float wd,
62	    float bc1, float bc2, int64_t N
63	) {
64	    const int64_t stride = prim::grid_stride() * UNROLL;
65	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
66	    for (int64_t base = base0; base < N; base += stride) {
67	        #pragma unroll
68	        for (int u = 0; u < UNROLL; ++u) {
69	            const int64_t i = base + u;
70	            if (i < N) {
71	                SG_SANITIZE_GRAD_INPLACE(grad, i);
72	                grokfast_fused_step(param, exp_avg, exp_avg_sq, ema, grad,
73	                                    gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
74	                                    bc1, bc2, i);
75	            }
76	        }
77	    }
78	}
79	
80	// FP32 vec4 fast path. Loads param/state/grad as float4 (one 128-bit
81	// transaction per 4 elements), then CALLS the canonical scalar
82	// grokfast_fused_step 4× on register-resident lanes — the math is NOT
83	// re-typed here (single-source guard), only the global traffic is widened.
84	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKFAST_MIN_BLOCKS)
85	grokfast_kernel_vec4_fp32(
86	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4, float4* ema4,
87	    const float4* grad4,
88	    float gf_alpha, float gf_lamb,
89	    float lr, float beta1, float beta2, float eps, float wd,
90	    float bc1, float bc2, int64_t N4
91	) {
92	    const int64_t stride = prim::grid_stride();
93	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
94	        float4 p  = prim::ld_f32v4(param4 + i);
95	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
96	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
97	        float4 e  = prim::ld_f32v4(ema4 + i);
98	        float4 g  = prim::ldg_f32v4(grad4 + i);
99	        ::grokking::sm90::sg_sanitize_grad4(g);
100	        // Call the canonical per-element step 4× on the register lanes.
101	        grokfast_fused_step(&p.x, &m.x, &v.x, &e.x, &g.x,
102	                            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
103	                            bc1, bc2, 0);
104	        grokfast_fused_step(&p.x, &m.x, &v.x, &e.x, &g.x,
105	                            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
106	                            bc1, bc2, 1);
107	        grokfast_fused_step(&p.x, &m.x, &v.x, &e.x, &g.x,
108	                            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
109	                            bc1, bc2, 2);
110	        grokfast_fused_step(&p.x, &m.x, &v.x, &e.x, &g.x,
111	                            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
112	                            bc1, bc2, 3);
113	        prim::st_f32v4(param4 + i, p);
114	        prim::st_f32v4(exp_avg4 + i, m);
115	        prim::st_f32v4(exp_avg_sq4 + i, v);
116	        prim::st_f32v4(ema4 + i, e);
117	    }
118	}
