120	void launch_grokfast_step(
121	    torch::Tensor& param,
122	    torch::Tensor& exp_avg,
123	    torch::Tensor& exp_avg_sq,
124	    torch::Tensor& ema,
125	    const torch::Tensor& grad,
126	    float gf_alpha, float gf_lamb,
127	    float lr, float beta1, float beta2, float eps, float wd,
128	    float bc1, float bc2
129	) {
130	    const int64_t N = param.numel();
131	    if (N == 0) return;
132	
133	    auto stream = at::cuda::getCurrentCUDAStream().stream();
134	
135	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
136	    prim::L2PersistScope l2(stream,
137	        exp_avg.data_ptr(), exp_avg.nbytes(),
138	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
139	
140	    const int block = SG_TUNED_BLOCK_SIZE;
141	    const int grid = static_cast<int>(
142	        std::min<int64_t>(65535, (N + block - 1) / block));
143	
144	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
145	                          grad.scalar_type() == torch::kFloat32;
146	
147	    // Autotuner picks the vector width: width 4 + 16B-aligned all-FP32 takes
148	    // the float4 fast path; otherwise the SG_TUNED_UNROLL scalar path runs.
149	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
150	        prim::is_vec4_alignable(param.data_ptr(), N) &&
151	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
152	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
153	        prim::is_vec4_alignable(ema.data_ptr(), N) &&
154	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
155	        const int64_t N4 = N / 4;
156	        const int grid4 = static_cast<int>(
157	            std::min<int64_t>(65535, (N4 + block - 1) / block));
158	        grokfast_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
159	            reinterpret_cast<float4*>(param.data_ptr<float>()),
160	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
161	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
162	            reinterpret_cast<float4*>(ema.data_ptr<float>()),
163	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
164	            gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
165	        SG_LAUNCH_CHECK(stream);
166	        return;
167	    }
168	
169	    AT_DISPATCH_FLOATING_TYPES_AND2(
170	        at::ScalarType::Half, at::ScalarType::BFloat16,
171	        param.scalar_type(), "grokfast_step", [&] {
172	            grokfast_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
173	                <<<grid, block, 0, stream>>>(
174	                param.data_ptr<scalar_t>(),
175	                exp_avg.data_ptr<float>(),
176	                exp_avg_sq.data_ptr<float>(),
177	                ema.data_ptr<float>(),
178	                grad.data_ptr<scalar_t>(),
179	                gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N);
180	            SG_LAUNCH_CHECK(stream);
181	        });
182	}
