185	// EMA-only update: ema = alpha * ema + (1 - alpha) * grad.
186	// No Adam step; used as a sub-operation by the fused path.
187	__global__ void grokfast_ema_kernel(
188	    float* grad, float* ema, float alpha, float lamb, int64_t N
189	) {
190	    const int64_t stride = prim::grid_stride();
191	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
192	        float g = ::grokking::sm90::sg_sanitize_grad(grad[i]);
193	        float e = alpha * ema[i] + (1.0f - alpha) * g;
194	        ema[i] = e;
195	        grad[i] = g + lamb * e;
196	    }
197	}
