199	void launch_fused_grokfast_ema(
200	    torch::Tensor grad, torch::Tensor ema, float alpha, float lamb
201	) {
202	    const int64_t N = grad.numel();
203	    if (N == 0) return;
204	    auto stream = at::cuda::getCurrentCUDAStream().stream();
205	    const int block = SG_TUNED_BLOCK_SIZE;
206	    const int grid = static_cast<int>(
207	        std::min<int64_t>(65535, (N + block - 1) / block));
208	    grokfast_ema_kernel<<<grid, block, 0, stream>>>(
209	        grad.data_ptr<float>(), ema.data_ptr<float>(), alpha, lamb, N);
210	    SG_LAUNCH_CHECK(stream);
211	}
