217	    float beta1, float beta2,
218	    float lr, float weight_decay, float eps,
219	    float bc1, float bc2
220	) {
221	    launch_grokfast_step(param, exp_avg, exp_avg_sq, ema, grad,
222	                         alpha, lamb, lr, beta1, beta2, eps, weight_decay,
223	                         bc1, bc2);
224	}
