226	void launch_multi_tensor_grokfast_ema(
227	    std::vector<torch::Tensor>& grads, std::vector<torch::Tensor>& ema_bufs,
228	    float alpha, float lamb
229	) {
230	    for (size_t i = 0; i < grads.size(); i++) {
231	        launch_fused_grokfast_ema(grads[i], ema_bufs[i], alpha, lamb);
232	    }
