134	// Validate every (param, grad) pair in a multi-tensor fused-step entrypoint.
135	inline void check_params_grads(
136	    const std::vector<torch::Tensor>& params,
137	    const std::vector<torch::Tensor>& grads,
138	    const char* where
139	) {
140	    TORCH_CHECK(params.size() == grads.size(), where,
141	                ": params.size() (", params.size(),
142	                ") != grads.size() (", grads.size(), ")");
143	    for (size_t i = 0; i < params.size(); ++i)
144	        check_param_grad(params[i], grads[i], where);
145	}
