56	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKFAST_MIN_BLOCKS)
57	grokfast_kernel(
58	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* ema,
59	    const GradT* grad,
60	    float gf_alpha, float gf_lamb,
61	    float lr, float beta1, float beta2, float eps, float wd,
62	    float bc1, float bc2, int64_t N
63	) {
64	    const int64_t stride = prim::grid_stride() * UNROLL;
65	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
66	    for (int64_t base = base0; base < N; base += stride) {
67	        #pragma unroll
68	        for (int u = 0; u < UNROLL; ++u) {
69	            const int64_t i = base + u;
70	            if (i < N) {
71	                SG_SANITIZE_GRAD_INPLACE(grad, i);
72	                grokfast_fused_step(param, exp_avg, exp_avg_sq, ema, grad,
73	                                    gf_alpha, gf_lamb, lr, beta1, beta2, eps, wd,
74	                                    bc1, bc2, i);
75	            }
76	        }
77	    }
78	}

